<?php $dir = __DIR__."/app/Models"; $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir)); $guarded = 0; $fillable = 0; $both = 0; $none = 0; foreach($it as $f) { if($f->getExtension() == "php") { $c = file_get_contents($f->getPathname()); $hasGuarded = str_contains($c, "protected \$guarded = []"); $hasFillable = str_contains($c, "protected \$fillable ="); if($hasGuarded && $hasFillable) $both++; elseif($hasGuarded) $guarded++; elseif($hasFillable) $fillable++; else $none++; } } echo "Guarded=[]: $guarded\nFillable: $fillable\nBoth: $both\nNone: $none\n";
